    import collections
    pts=[(i,j) for i in range(len(I)) for j in range(len(I[0])) if I[i][j]]
    seen=set(); comps=[]
    for p in pts:
        if p in seen: continue
        stack=[p]; comp=[]
        while stack:
            x,y=stack.pop()
            if (x,y) in seen or not(0<=x<len(I)) or not(0<=y<len(I[0])) or I[x][y]==0: continue
            seen.add((x,y)); comp.append((x,y))
            for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)): stack.append((x+dx,y+dy))
        comps.append(comp)
    O=[row[:] for row in I]
    for comp in comps:
        rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        # peel rings: repeatedly take perimeter cells of current box that are in comp
        rem=set(comp); rings=[]
        while True:
            cur={(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1)} & rem
            if not cur: break
            rings.append(cur)
            # shrink
            newrem={p for p in rem if r0<p[0]<r1 and c0<p[1]<c1}
            rem=newrem; r0+=1; r1-=1; c0+=1; c1-=1
        # each ring should be uniform color; collect
        seq=[]
        for rng in rings:
            col=collections.Counter(I[p[0]][p[1]] for p in rng)
            if len(col)>1:
                print("MULTI", col, rings.index(rng)); 
            seq.append(col.most_common(1)[0][0])
        seq=seq[::-1]
        # repaint: outermost ring gets last element etc. assign reversed seq to rings in order
        idx=0
        for rng in rings:
            for p in rng:
                O[p[0]][p[1]]=seq[-idx]
            idx+=1
    return O
