    sr=[p[0] for p in rest]; sc=[p[1] for p in rest]
    nr0,nr1,nc0,nc1=min(sr),max(sr),min(sc),max(sc)
    # prune interior zeros: bbox may contain zeros not in comp -> shrink tight to comp only
