# So rule: frames_out[k].ring recolored by frames_out[n-1-k]'s ORIGINAL color. Test it.
def solve(I):
    H,W=len(I),len(I[0])
    seen=set(); comps=[]
    for i in range(H):
        for j in range(W):
            if I[i][j] and (i,j) not in seen:
                st=[(i,j)]; comp=[]
                while st:
                    x,y=st.pop()
                    if (x,y) in seen or not(0<=x<H) or not(0<=y<W) or I[x][y]==0: continue
                    seen.add((x,y)); comp.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)): st.append((x+dx,y+dy))
                comps.append(comp)
    O=[row[:] for row in I]
    def decompose(S,R0,R1,C0,C1):
        cands=[]
        for rlo in range(R0,R1+1):
            for rhi in range(rlo+1,R1+1):
                for clo in range(C0,C1+1):
                    for chi in range(clo+1,C1+1):
                        ok=True
                        for c in range(clo,chi+1):
                            if (rlo,c) not in S or (rhi,c) not in S: ok=False;break
                        if not ok: continue
                        for r in range(rlo,rhi+1):
                            if (r,clo) not in S or (r,chi) not in S: ok=False;break
                        if not ok: continue
                        vals={I[rlo][c] for c in range(clo,chi+1)}|{I[rhi][c] for c in range(clo,chi+1)}|{I[r][clo] for r in range(rlo,rhi+1)}|{I[r][chi] for r in range(rlo,rhi+1)}
                        if len(vals)!=1: continue
                        inner={(r,c) for r in range(rlo+1,rhi) for c in range(clo+1,chi)}
                        # allow interior empty OR containing other frames (non-uniform allowed)
                        cands.append(((rhi-rlo+1)*(chi-clo+1),vals.pop(),(rlo,rhi,clo,chi)))
        if not cands: return None
        cands.sort(key=lambda x:-x[0])
        return cands[0]
    for comp in comps:
        S=set(comp); R0=min(r for r,_ in comp); R1=max(r for r,_ in comp); C0=min(c for _,c in comp); C1=max(c for _,c in comp)
        frames_out=[]; cur=(R0,R1,C0,C1)
        while True:
            res=decompose(S,*cur)
            if res is None: break
            col,res_c=res[1],res[2]
            frames_out.append((res_c[0],res_c[1],res_c[2],res_c[3],col))
            ring={(r,c) for r in range(res_c[0],res_c[1]+1) for c in (res_c[2],res_c[3])}|{(r,c) for c in range(res_c[2],res_c[3]+1) for r in (res_c[0],res_c[1])}
            S-=ring
            cur=(res_c[0]+1,res_c[1]-1,res_c[2]+1,res_c[3]-1)
            if not(cur[0]<=cur[1] and cur[2]<=cur[3]): break
        n=len(frames_out)
        for k,(rlo,rhi,clo,chi,col_orig) in enumerate(frames_out):
            newcol=frames_out[n-1-k][4]
            for r in range(rlo,rhi+1):
                for c in range(clo,chi+1):
                    if r in (rlo,rhi) and clo<=c<=chi: O[r][c]=newcol
                    elif c in (clo,chi) and rlo<=r<=rhi: O[r][c]=newcol
    return O
