def comps_of(I):
    H,W=len(I),len(I[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if I[i][j]!=0 and (i,j) not in seen:
                st=[(i,j)]; comp=[]
                while st:
                    x,y=st.pop()
                    if (x,y) in seen or not(0<=x<H) or not(0<=y<W) or I[x][y]==0: continue
                    seen.add((x,y)); comp.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)): st.append((x+dx,y+dy))
                out.append(comp)
    return out

def maximal_rects(I,R0,R1,C0,C1):
    res=[]
    for rl in range(R0,R1+1):
        for rh in range(rl,R1+1):
            for cl in range(C0,C1+1):
                for ch in range(cl,C1+1):
                    v=I[rl][cl]
                    ok=all(I[rl][c]==v and I[rh][c]==v for c in range(cl,ch+1)) and all(I[r][cl]==v and I[r][ch]==v for r in range(rl,rh+1))
                    if not ok: continue
                    ext_up = rl>0 and all(I[rl-1][c]==v for c in range(cl,ch+1))
                    ext_dn = rh<R1 and all(I[rh+1][c]==v for c in range(cl,ch+1))
                    ext_lf = cl>C0 and all(I[r][cl-1]==v for r in range(rl,rh+1))
                    ext_rt = ch<C1 and all(I[r][ch+1]==v for r in range(rl,rh+1))
                    if not (ext_up or ext_dn or ext_lf or ext_rt):
                        res.append((rl,rh,cl,ch,v))
    return res

def peel_chain(I,comp):
    rr=[r for r,_ in comp]; cc=[c for _,c in comp]
    R0,R1,C0,C1=min(rr),max(rr),min(cc),max(cc)
    frames=maximal_rects(I,R0,R1,C0,C1)
    chain=[]; rem_frames=list(frames)
    while rem_frames:
        f=max(rem_frames,key=lambda g:(g[1]-g[0]+1)*(g[3]-g[2]+1))
        chain.append(f)
        rem_frames=[g for g in rem_frames if g[0]>f[0] and g[1]<f[1] and g[2]>f[2] and g[3]<f[3]]
    return chain

def solve(I):
    O=[row[:] for row in I]
    for comp in comps_of(I):
        cs=peel_chain(I,comp)
        n=len(cs)
        seq=[cs[k][4] for k in range(n)]
        for k,f in enumerate(cs):
            col=seq[n-1-k]
            for r in range(f[0],f[1]+1):
                for c in range(f[2],f[3]+1):
                    if r in (f[0],f[1]) or c in (f[2],f[3]): O[r][c]=col
    return O
print(solve(D)==E)
for i,(a,b) in enumerate(zip(solve(D),E)):
    if a!=b: print(i,''.join(str(x) for x in a),'|',''.join(str(x) for x in b))

