import numpy as np
def rect_comps(g):
    g=np.array(g); seen=np.zeros_like(g,bool); out=[]
    H,W=g.shape
    for r in range(H):
        for c in range(W):
            v=g[r,c]
            if v!=0 and not seen[r,c]:
                # flood same color 4-conn
                st=[(r,c)]; seen[r,c]=1; comp=[]
                while st:
                    y,x=st.pop(); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny,nx]==v and not seen[ny,nx]:
                            seen[ny,nx]=1; st.append((ny,nx))
                ys=[a for a,b in comp]; xs=[b for a,b in comp]
                h=max(ys)-min(ys)+1; w=max(xs)-min(xs)+1
                out.append((v,len(comp)==h*w,len(comp),h,w))
    return out
